CREATE TABLE acquisition_anomalies (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE CHECK (typeof(device_id) = 'text' AND length(device_id) > 0), point_id TEXT CHECK (point_id IS NULL OR (typeof(point_id) = 'text' AND length(point_id) > 0)), kind TEXT NOT NULL CHECK (kind IN ('disconnected', 'stale', 'frozen')), started_at INTEGER NOT NULL CHECK (typeof(started_at) = 'integer'), ended_at INTEGER CHECK (ended_at IS NULL OR (typeof(ended_at) = 'integer' AND ended_at >= started_at)), last_value TEXT, detail TEXT NOT NULL DEFAULT '', CHECK ((kind = 'disconnected') = (point_id IS NULL)));
CREATE UNIQUE INDEX idx_acquisition_anomalies_active ON acquisition_anomalies (device_id, COALESCE(point_id, ''), kind) WHERE ended_at IS NULL;
CREATE INDEX idx_acquisition_anomalies_device_started ON acquisition_anomalies (device_id, started_at, id)
